import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
for k in G: print(k, len(G[k]), len(G[k][0]))

def transform(g):
    h,w=len(g),len(g[0]); bg=g[0][0]
    out=[row[:] for row in g]
    seeds=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]!=bg]
    DIRS=[(-1,-1),(-1,1),(1,-1),(1,1)]
    def aligned(a,b):
        return abs(a[0]-b[0])==abs(a[1]-b[1])
    def draw(start,d,color):
        r,c=start[0]+d[0],start[1]+d[1]
        while 0<=r<h and 0<=c<w:
            if out[r][c]!=bg: break
            out[r][c]=color; r+=d[0]; c+=d[1]
    # 1s first: single ray toward nearest diagonally-aligned mark, else down-right
    ones=[s for s in seeds if s[2]==1]; sixes=[s for s in seeds if s[2]==6]
    for s in ones:
        aligned_mk=[m for m in seeds if m!=s and aligned(s,m)]
        if aligned_mk:
            m=min(aligned_mk,key=lambda m:abs(m[0]-s[0]))
            d=(1 if m[0]>s[0] else -1, 1 if m[1]>s[1] else -1)
        else:
            d=(1,1)
        draw(s,d,1)
    for s in sixes:
        for d in DIRS: draw(s,d,6)
    return out

for k in ['Demo pair 1','Demo pair 2']:
    i=G[k+' input']; o=G[k+' output']
    print(k, transform(i)==o)
    if transform(i)!=o:
        for r in transform(i): print(r)
        print('---')
        for r in o: print(r)

